INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「ネット上の誹謗中傷」に関して、法的に問われる可能性のある責任はどれですか？', '["名誉毀損罪や侮辱罪などの刑事・民事責任","ネット上なら誰でも自由に発言できるため責任はない","謝罪文を投稿すれば全ての法的手続きは終了する","IDを削除すれば過去の投稿は遡及されない"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「デジタルタトゥー」とはどのような状態を指しますか？', '["デジタル機器で作った入れ墨の画像","一度ネットに公開した情報は完全に消去することが困難であること","最新の顔認証技術のこと","ネット上の犯罪者が持つ独特のニックネーム"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'マルウェアとは何ですか？', '["最新のPC周辺機器の総称","悪意のあるソフトウェアの総称","セキュリティソフトの最新版","ネット接続を高速化するプログラム"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'IDやパスワードを盗み取る攻撃手法として知られる「ショルダーハッキング」とは何ですか？', '["肩を叩いてパスワードを教えさせる攻撃","肩越しに覗き見て情報を盗むこと","サーバーの肩を狙った攻撃手法","遠隔操作で肩のコリをほぐすアプリの悪用"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'フィッシング詐欺メールを見抜くヒントとして、最も疑わしいものはどれですか？', '["宛名が「お客様」など一般的で、緊急性を煽る内容である","送信者のメールアドレスが企業のドメインと完全に一致している","文章が非常に丁寧で、誤字脱字が全くない","リンク先が公式サイトと同じURLである"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'ワンクリック詐欺に遭遇した時の最も適切な対処法はどれですか？', '["表示された金額を一旦支払う","慌てずに無視する。安易に連絡を取らない","画面の指示通りにアンインストールを行う","警察に電話する前に、犯人にメールで苦情を言う"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'パスワードを強固にするための条件として、最も推奨されるのはどれですか？', '["自分に関連する単語（ペットの名前など）を使う","英大文字、小文字、数字、記号を組み合わせる","覚えやすいように自分の電話番号を含める","短くて入力しやすいものにする"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'SNSで「拡散希望」として流れてくる未確認情報の取り扱いとして、最も適切なものは？', '["すぐにシェアして友人に知らせる","情報の出所を確認し、信頼できるか見極める","面白い内容なら嘘でも良いので広める","コメント欄で否定的な意見を書き込む"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'コンピュータウイルスへの対策として、最も基本的なものはどれですか？', '["毎日PCを再起動する","OSやアプリを最新の状態に保つ（アップデート）","画面を清潔に保つ","キーボードを強く叩く"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「ソーシャルエンジニアリング」の説明として正しいものはどれですか？', '["ネット上の技術的な脆弱性を突く攻撃","人の心理的な隙や行動のミスを突いて情報を盗む手法","SNSの友人関係を分析するマーケティング手法","人工知能を使って社会問題を解決する技術"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'クレジットカード情報が必要なサイトで、URLの冒頭が何であれば比較的安全と言えますか？', '["http://","https://","ftp://","www.net/"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'スマホで「権限」の許可を求められた際、注意すべきことは？', '["全てのアプリには全ての権限を許可するのがルール","アプリの機能に関係のない個人情報（連絡先や位置情報）へのアクセス要求は拒否する","有名なアプリであれば確認せずに許可して良い","権限を許可しないとスマホが故障する"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '偽のサポート画面が表示された際の正しい対応は？', '["画面に表示された電話番号に連絡する","慌てずにブラウザを閉じるか、PCを再起動する","指示通りにクリーニングソフトをダウンロードする","クレジットカード情報を入力して解決を図る"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '著作権についての説明として正しいものはどれですか？', '["ネット上の画像は、誰でも自由に加工して自分のサイトに載せられる","他人が作成したイラストや写真は、無断でSNSのアイコンに使用してはいけない","有名人の写真であれば著作権は発生しない","ダウンロードしたものは全て個人利用なら著作権に関係ない"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'パスワードを使い回すことの最大のリスクは何ですか？', '["パスワードを忘れる回数が増える","一箇所から漏洩すると、他のサービスも次々に不正利用される","パスワードを入力する時間が無駄になる","サイトの運営者に迷惑がかかる"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「クッキー（Cookie）」についての説明として正しいものは？', '["PCをウイルスから守るためのセキュリティ機能","サイト訪問者の閲覧履歴などを一時的にブラウザに保存する仕組み","インターネット接続を高速化する通信規格","悪意のあるWebサイトを自動で遮断する機能"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'VPN（仮想専用線）を利用する主な目的は何ですか？', '["インターネットを高速化するため","通信を暗号化し、盗聴や覗き見から保護するため","メールの受信時間を短縮するため","PCのストレージ容量を増やすため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '公共の場でPCを利用する際、離席時にすべきことは？', '["画面を明るくして帰る","画面をロックする（Windowsキー + Lなど）","電源を切る","近くの人に見ておいてもらうよう頼む"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'ランサムウェアの特徴として正しいものは？', '["PCの動作を極端に速くするソフト","データを人質に取り、身代金を要求するマルウェア","インターネット上の広告を非表示にするアプリ","不要なファイルを探して削除するソフト"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「スミッシング」とはどのような詐欺のことですか？', '["スマホの充電器を偽装したハッキング","SMS（ショートメッセージ）を利用したフィッシング詐欺","動画サイトでの偽の広告詐欺","SNSでの出会い系詐欺"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'フリーWi-Fiに接続する際、末尾が「.open」や暗号化されていないものはなぜ危険ですか？', '["通信速度が遅いから","通信内容を第三者に傍受される可能性があるから","バッテリーの消費が激しくなるから","運営会社が倒産している可能性が高いから"]', 1, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'SNSで知らない人から突然メッセージが届いた時の対応として適切なものは？', '["丁寧にお礼を返信して交流を深める","リンクをクリックして相手を確認する","無視またはブロックし、必要なら通報する","電話番号を聞いて直接話す"]', 2, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', '「プライバシー設定」を公開範囲に制限しておくべき最大の理由は？', '["フォロワーを増やすため","個人情報を守り、ストーカーや迷惑行為を防ぐため","スマホの処理速度を上げるため","ネットの通信料を節約するため"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'OS（オペレーティングシステム）のアップデートが推奨される理由は？', '["アプリを全て有料にするため","セキュリティ上の脆弱性を修正し、安全性を保つため","スマホのデザインを強制的に変えるため","新しいゲームをインストールしやすくするため"]', 1, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('all', 'social_studies', 'ネット上の買い物で「代金引換」以外の支払い方法として安全なものはどれですか？', '["怪しいサイトでの直接振り込み","大手で実績のある決済サービスやクレジットカード","SNS上の個人への直接送金","暗号資産での匿名送金"]', 1, 2);
